/// An infantry type's data.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct InfantryData {
    /// The constructor's type argument (normally the slot's own type).
    pub kind: InfantryType,
    /// INI / art name.
    pub ini_name: &'static str,
    /// Build level (tech level).
    pub tech_level: u8,
    /// Prerequisite buildings, as a bit mask of `BuildingType` ids.
    pub prerequisites: u64,
    /// `is_female` constructor argument.
    pub is_female: bool,
    /// `is_leader` constructor argument.
    pub is_leader: bool,
    /// `is_crawling` constructor argument.
    pub is_crawling: bool,
    /// `is_civilian` constructor argument.
    pub is_civilian: bool,
    /// `is_nominal` constructor argument.
    pub is_nominal: bool,
    /// `is_fraidycat` constructor argument.
    pub is_fraidycat: bool,
    /// `is_capture` constructor argument.
    pub is_capture: bool,
    /// `is_theater` constructor argument.
    pub is_theater: bool,
    /// Shots before reloading (-1 unlimited).
    pub ammo: i32,
    /// `firelaunch` constructor argument.
    pub fire_launch: i32,
    /// `pronelaunch` constructor argument.
    pub prone_launch: i32,
    /// Full strength as written (buildings get double this; see `max_strength`).
    pub strength: u16,
    /// Sight range in cells.
    pub sight_range: i32,
    /// Cost to build, in credits.
    pub cost: i32,
    /// First scenario it's available in.
    pub scenario: i32,
    /// Risk rating.
    pub risk: i32,
    /// Reward rating.
    pub reward: i32,
    /// Houses that may own it, as a bit mask of `House` ids.
    pub owners: u32,
    /// `primary` constructor argument.
    pub primary: Option<Weapon>,
    /// `secondary` constructor argument.
    pub secondary: Option<Weapon>,
    /// Top speed on the game's 0..=255 scale.
    pub max_speed: u8,
}

