/// A projectile type's data.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct BulletData {
    /// The constructor's type argument (normally the slot's own type).
    pub kind: Bullet,
    /// INI / art name.
    pub ini_name: &'static str,
    /// `is_high` constructor argument.
    pub is_high: bool,
    /// `is_homing` constructor argument.
    pub is_homing: bool,
    /// `is_arcing` constructor argument.
    pub is_arcing: bool,
    /// `is_dropping` constructor argument.
    pub is_dropping: bool,
    /// `is_invisible` constructor argument.
    pub is_invisible: bool,
    /// `is_proximity_armed` constructor argument.
    pub is_proximity_armed: bool,
    /// `is_flame_equipped` constructor argument.
    pub is_flame_equipped: bool,
    /// `is_fueled` constructor argument.
    pub is_fueled: bool,
    /// `is_faceless` constructor argument.
    pub is_faceless: bool,
    /// `is_inaccurate` constructor argument.
    pub is_inaccurate: bool,
    /// `is_translucent` constructor argument.
    pub is_translucent: bool,
    /// `is_antiaircraft` constructor argument.
    pub is_antiaircraft: bool,
    /// Ticks before it can explode.
    pub arming: i32,
    /// Range override.
    pub range: i32,
    /// Top speed on the game's 0..=255 scale.
    pub max_speed: u8,
    /// Rate of turn.
    pub rot: i32,
    /// Warhead.
    pub warhead: Option<Warhead>,
    /// Explosion on impact.
    pub explosion: Option<Anim>,
}

