/// A terrain template's data.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct TemplateData {
    /// The constructor's type argument (normally the slot's own type).
    pub kind: TemplateType,
    /// INI / art name.
    pub ini_name: &'static str,
    /// Theaters it exists in, as a bit mask of `Theater` ids.
    pub theaters: u8,
    /// The ground it makes.
    pub land: Land,
    /// Width in cells.
    pub width: i32,
    /// Height in cells.
    pub height: i32,
    /// The ground its `alt_icons` make instead.
    pub alt_land: Land,
    /// Icons that make `alt_land` instead of `land`.
    pub alt_icons: &'static [u8],
}

