/// A terrain object's (tree's, rock's) data.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct TerrainData {
    /// The constructor's type argument (normally the slot's own type).
    pub kind: TerrainType,
    /// INI / art name.
    pub ini_name: &'static str,
    /// Theaters it exists in, as a bit mask of `Theater` ids.
    pub theaters: u8,
    /// Offset of its base from its cell's corner, in leptons.
    pub center_base: Coord,
    /// `is_spawn` constructor argument.
    pub is_spawn: bool,
    /// `is_destroyable` constructor argument.
    pub is_destroyable: bool,
    /// `is_transformable` constructor argument.
    pub is_transformable: bool,
    /// `is_flammable` constructor argument.
    pub is_flammable: bool,
    /// `is_crushable` constructor argument.
    pub is_crushable: bool,
    /// `is_selectable` constructor argument.
    pub is_selectable: bool,
    /// `is_legal_target` constructor argument.
    pub is_legal_target: bool,
    /// `is_insignificant` constructor argument.
    pub is_insignificant: bool,
    /// `is_immune` constructor argument.
    pub is_immune: bool,
    /// Full strength as written (buildings get double this; see `max_strength`).
    pub strength: u16,
    /// `armor` constructor argument.
    pub armor: Armor,
    /// Occupied cells, as offsets from its cell.
    pub occupy: &'static [i16],
    /// Overlapped (drawn over) cells, as offsets.
    pub overlap: &'static [i16],
}

