/// An overlay type's data.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct OverlayData {
    /// The constructor's type argument (normally the slot's own type).
    pub kind: OverlayType,
    /// INI / art name.
    pub ini_name: &'static str,
    /// The ground it makes (anything but clear overrides the template).
    pub ground: Land,
    /// Damage stages, for walls.
    pub damage_levels: i32,
    /// Damage per stage, for walls.
    pub damage_points: i32,
    /// `isradarvisible` constructor argument.
    pub is_radar_visible: bool,
    /// `iswooden` constructor argument.
    pub is_wooden: bool,
    /// `istarget` constructor argument.
    pub is_target: bool,
    /// `iscrushable` constructor argument.
    pub is_crushable: bool,
    /// `istiberium` constructor argument.
    pub is_tiberium: bool,
    /// `high` constructor argument.
    pub is_high: bool,
    /// Theaters it exists in, as a bit mask of `Theater` ids.
    pub theaters: u8,
    /// `walltype` constructor argument.
    pub is_wall: bool,
    /// `iscrate` constructor argument.
    pub is_crate: bool,
}

