/// A weapon's data (`WeaponTypeClass`).
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct WeaponData {
    /// Which weapon this is.
    pub kind: Weapon,
    /// Projectile fired.
    pub fires: Option<Bullet>,
    /// Damage per shot.
    pub attack: u8,
    /// Rate of fire (ticks between shots).
    pub rof: u8,
    /// Range in leptons.
    pub range: i32,
    /// Sound when fired.
    pub sound: Option<Voc>,
    /// Muzzle animation.
    pub anim: Option<Anim>,
}

