/// How a kind of ground affects movement and building (`GroundType`).
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub struct GroundData {
    /// Which ground this is.
    pub land: Land,
    /// Speed on it for each `Locomotion`, 0 (impassable) to 255 (full speed).
    pub speed: [u8; 7],
    /// Whether buildings can be placed on it.
    pub buildable: bool,
}

